import 'dart:typed_data';

import 'file_service_io.dart'
    if (dart.library.js_interop) 'file_service_web.dart' as impl;

/// Saves generated bytes (a receipt, an export) in the way each platform
/// expects, without callers importing `dart:io` or `package:web`.
///
/// The implementation is picked at compile time:
///  * `file_service_io.dart`  - Android / iOS / desktop, uses `dart:io`.
///  * `file_service_web.dart` - browsers (JS and WASM), uses `package:web`.
///
/// `dart.library.js_interop` is the condition to use: it is true for both
/// dart2js and dart2wasm, whereas the older `dart.library.html` is false under
/// WASM and would silently select the `dart:io` file and break the build.
abstract interface class FileService {
  /// The implementation for the platform this build targets.
  static final FileService instance = impl.createFileService();

  /// Persists [bytes] as [fileName].
  ///
  /// On the web this triggers a browser download. On native platforms the
  /// file is written to the system temporary directory and its path returned.
  Future<SavedFile> saveBytes({
    required Uint8List bytes,
    required String fileName,
    String mimeType = 'application/octet-stream',
  });
}

/// Where a [FileService.saveBytes] call put the file.
class SavedFile {
  const SavedFile({required this.location, required this.isDownload});

  /// A filesystem path on native platforms; the suggested file name on web.
  final String location;

  /// True when the browser was asked to download the file (web), in which
  /// case the app cannot know where the user's browser stored it.
  final bool isDownload;
}

/// Strips anything that could act as a path, so a caller-supplied name can
/// never escape the target directory or confuse the browser.
String sanitizeFileName(String fileName) {
  final cleaned = fileName
      .replaceAll(RegExp(r'[\\/:*?"<>|\x00-\x1F]'), '_')
      .replaceAll(RegExp(r'^\.+'), '')
      .trim();
  return cleaned.isEmpty ? 'download' : cleaned;
}
